/*
 * gen-badge-assets.mjs - turn 吧唧交互规范's icons and prompt sounds into the
 * firmware's asset tables.
 *
 * The interaction specification is the only source of truth for the badge UI. The
 * layout half is already generated by tools/gen-badge-ui.mjs into
 * main/ui/badge_spec_data.{h,c}; this script is the assets half:
 *
 *   main/ui/badge_assets_data.c   the pixels and the samples
 *   main/ui/badge_assets.c        the accessors declared by main/ui/badge_assets.h
 *
 * Icons are decoded from the package's 16x16 PNGs with Node's built-in zlib -- no
 * npm dependency, no image library, no PNG decoder in the firmware (LV_USE_LODEPNG
 * is off on purpose). Every icon becomes RGBA8888 so badge_paint can blit it with
 * the integer nearest-neighbour scale the specification asks for.
 *
 * Sounds are vendored from the package's 16 kHz 16-bit mono WAVs and then checked
 * sample for sample against the package's own sounds/badge_sounds.c, so a corrupt
 * WAV cannot silently ship.
 *
 * Like gen-badge-ui.mjs it is deliberately strict:
 *   - an icon badge_spec_data.c names but the package has no PNG for is an error;
 *   - a PNG whose size is not BADGE_ICON_PX x BADGE_ICON_PX is an error;
 *   - a sound that is not 16 kHz 16-bit mono, or that disagrees with
 *     badge_sounds.c, is an error;
 *   - the sound order is tied to the badge_snd_t enum in badge_assets.h, so
 *     reordering the enum without touching the spec cannot pass.
 * A PNG the package ships but badge_spec.json never references is reported loudly
 * and recorded in the generated header, because it means the spec and the package
 * have drifted (see docs/badge-assets-integration.md); --strict makes it fatal.
 *
 * The PNG decoder is hand-written, so it was verified once against an independent
 * one: all 28 package icons decoded with Pillow and diffed byte for byte against
 * the emitted badge_icon_*_data[] arrays (0 mismatches). That is how the
 * absolute-vs-row-relative bit index bug in readSample() was found -- a wrong row
 * still yields a plausible icon. If this decoder is ever changed, repeat that
 * diff; docs/badge-assets-integration.md has the recipe.
 *
 * Usage:  node tools/gen-badge-assets.mjs [--spec-dir <dir>] [--spec-data <file>]
 *                                        [--out-dir <dir>] [--fonts-dir <dir>]
 *                                        [--check] [--strict]
 *         --check  verify the generated files are current, write nothing
 *         --strict make an icon the package ships but badge_spec.json never
 *                  references a fatal error instead of a warning
 */
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateSync } from 'node:zlib';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, '..');

const argv = process.argv.slice(2);
const argOf = (name, dflt) => {
  const i = argv.indexOf(name);
  return i >= 0 && argv[i + 1] ? argv[i + 1] : dflt;
};
const CHECK_ONLY = argv.includes('--check');
const STRICT = argv.includes('--strict');
const SPEC_DIR = resolve(
  argOf('--spec-dir', join(ROOT, '_ref', 'baji-spec', '吧唧交互规范')),
);
const UI_DIR = resolve(argOf('--out-dir', join(ROOT, 'main', 'ui')));
const SPEC_DATA_C = resolve(argOf('--spec-data', join(UI_DIR, 'badge_spec_data.c')));
const SPEC_DATA_H = resolve(join(dirname(SPEC_DATA_C), 'badge_spec_data.h'));
const FONTS_DIR = resolve(argOf('--fonts-dir', join(UI_DIR, 'fonts')));
const ICONS_DIR = join(SPEC_DIR, 'icons');
const SOUNDS_DIR = join(SPEC_DIR, 'sounds');
const SPEC_JSON = join(SPEC_DIR, 'badge_spec.json');

/* --------------------------------------------------------------- helpers ----*/

const fail = (msg) => {
  console.error(`gen-badge-assets: ERROR: ${msg}`);
  process.exit(1);
};

const cString = (s) =>
  '"' +
  String(s)
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\t/g, '\\t')
    // Keep the source ASCII-safe for any compiler locale, the same way the rest
    // of this firmware writes Chinese as UTF-8 escapes in generated data.
    .replace(/[^\x20-\x7e]/gu, (ch) => {
      const cp = ch.codePointAt(0);
      return cp > 0xffff
        ? `\\U${cp.toString(16).padStart(8, '0')}`
        : `\\u${cp.toString(16).padStart(4, '0')}`;
    }) +
  '"';

/* A C identifier fragment, the same normalisation gen-badge-ui.mjs uses. */
const ident = (s) => String(s).replace(/[^A-Za-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

/* ------------------------------------------------------------ the package ---*/

for (const [what, p] of [
  ['icons directory', ICONS_DIR],
  ['sounds directory', SOUNDS_DIR],
  ['badge_spec.json', SPEC_JSON],
  ['generated badge_spec_data.c', SPEC_DATA_C],
  ['generated badge_spec_data.h', SPEC_DATA_H],
]) {
  if (!existsSync(p)) {
    fail(
      `${what} not found at ${p}\n` +
        '  The interaction specification ships as a zip; extract it to _ref/baji-spec/ ' +
        '(see docs/badge-spec.md) or pass --spec-dir <path>.',
    );
  }
}
for (const face of ['badge_f16.c', 'badge_f20.c', 'badge_f24.c', 'badge_n40.c']) {
  if (!existsSync(join(FONTS_DIR, face))) {
    fail(
      `main/ui/fonts/${face} is missing.\n` +
        `  badge_assets.c declares badge_${face.slice(6, -2)} extern; copy the four font ` +
        'files out of the specification package into main/ui/fonts/ (see ' +
        'docs/badge-assets-integration.md).',
    );
  }
}

/* ------------------------------------------------- the frozen headers --------*/

/*
 * The asset sizes are pinned by hand-written headers this script must not edit
 * (main/ui/badge_spec.h, main/ui/badge_assets.h). Read them and prove the package
 * still agrees instead of trusting a comment.
 */
const specH = readFileSync(join(UI_DIR, 'badge_spec.h'), 'utf8');
const assetsH = readFileSync(join(UI_DIR, 'badge_assets.h'), 'utf8');

const defineOf = (text, name, file) => {
  const m = text.match(new RegExp(`^#define\\s+${name}\\s+(\\d+)`, 'm'));
  if (!m) fail(`${file} does not define ${name}`);
  return Number(m[1]);
};

const ICON_PX = defineOf(specH, 'BADGE_ICON_PX', 'main/ui/badge_spec.h');
const PCM_RATE = defineOf(assetsH, 'BADGE_PCM_RATE', 'main/ui/badge_assets.h');

/* The badge_snd_t enum order is the order badge_pcm() indexes with, so it is the
 * order the spec's sounds must be emitted in. */
const sndEnum = assetsH.match(/typedef\s+enum\s*\{([\s\S]*?)\}\s*badge_snd_t\s*;/);
if (!sndEnum) fail('main/ui/badge_assets.h does not declare enum badge_snd_t');
const SND_ENUM = [...sndEnum[1].matchAll(/\b(SND_[A-Z_]+)\b/g)].map((m) => m[1]);
if (SND_ENUM.length === 0 || SND_ENUM[SND_ENUM.length - 1] !== 'SND_COUNT') {
  fail(`badge_snd_t does not end in SND_COUNT (got ${SND_ENUM.join(', ')})`);
}
const SND_NAMES = SND_ENUM.slice(0, -1); /* SND_PET .. SND_ERROR */

/* The camelCase keys of badge_spec.json's `sounds` object, in enum order. */
const SND_SPEC_KEYS = ['pet', 'careDone', 'meet', 'wake', 'error'];
if (SND_NAMES.length !== SND_SPEC_KEYS.length) {
  fail(
    `badge_snd_t has ${SND_NAMES.length} sounds but badge_spec.json's "sounds" has ` +
      `${SND_SPEC_KEYS.length}; update main/ui/badge_assets.h and this script together`,
  );
}

const S = JSON.parse(readFileSync(SPEC_JSON, 'utf8'));

/* ------------------------------------------------------- icons: the order ---*/

/*
 * badge_icon_names[] in the generated tables is the index order badge_icon_rgba()
 * uses. Parse it rather than re-deriving the list from the JSON: the whole point
 * is to prove the two halves of the generator agree, so one of them has to be
 * read back from disk.
 */
const specDataC = readFileSync(SPEC_DATA_C, 'utf8');
const namesBlock = specDataC.match(
  /badge_icon_names\[BADGE_ICON_COUNT\]\s*=\s*\{([\s\S]*?)\n\};/,
);
if (!namesBlock) {
  fail(
    `could not find badge_icon_names[BADGE_ICON_COUNT] in ${SPEC_DATA_C}\n` +
      '  Regenerate it with: node tools/gen-badge-ui.mjs',
  );
}
const ICON_NAMES = [...namesBlock[1].matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) =>
  JSON.parse(`"${m[1]}"`),
);
if (ICON_NAMES.length === 0) fail(`${SPEC_DATA_C}: badge_icon_names[] is empty`);

const specDataH = readFileSync(SPEC_DATA_H, 'utf8');
const declaredCount = defineOf(specDataH, 'BADGE_ICON_COUNT', 'main/ui/badge_spec_data.h');
if (declaredCount !== ICON_NAMES.length) {
  fail(
    `badge_spec_data.h says BADGE_ICON_COUNT ${declaredCount} but badge_spec_data.c ` +
      `lists ${ICON_NAMES.length} names`,
  );
}

/* `name@3x.png` is the same artwork at 3x (the firmware blits 1x at an integer
 * scale instead), and `_..png` is the package's contact sheet of the whole set,
 * not an icon. Both are skipped by name, and a skipped file is never silently
 * treated as a missing asset because only badge_icon_names[] drives the table. */
const onDisk = readdirSync(ICONS_DIR)
  .filter((f) => f.endsWith('.png') && !f.includes('@') && !f.startsWith('_'))
  .map((f) => f.slice(0, -4))
  .sort();

const missing = ICON_NAMES.filter((n) => !onDisk.includes(n));
if (missing.length) {
  fail(
    `${missing.length} icon(s) named by badge_spec_data.c have no PNG in ${ICONS_DIR}:\n` +
      missing.map((n) => `    ${n}.png`).join('\n') +
      '\n  The specification package is incomplete, or badge_spec.json was revised ' +
      'and the package was not.',
  );
}
const IN_SPEC = new Set(ICON_NAMES);
const unreferenced = onDisk.filter((n) => !IN_SPEC.has(n));

/*
 * A PNG the package ships but badge_icon_names[] has no slot for is a
 * disagreement between the specification and the package. It is not fatal by
 * default: the table this script emits is still exactly badge_icon_names[] in
 * order, with every icon it names, which is what the firmware needs. (Today's case
 * is icons/bolt.png -- the reference renderer draws it in the battery element, but
 * no badge_spec.json entry references "bolt", so there is no index to emit it at.
 * See docs/badge-assets-integration.md.)
 *
 * --strict promotes it to an error for anyone who wants the two sets to be equal,
 * which is what a spec revision should aim for.
 */
if (STRICT && unreferenced.length) {
  fail(
    `${unreferenced.length} icon(s) ship in ${ICONS_DIR} but badge_spec.json references ` +
      'none of them, so they have no index in badge_icon_names[]:\n' +
      unreferenced.map((n) => `    ${n}.png`).join('\n') +
      '\n  Add the element that draws them to the specification and regenerate it, or ' +
      'remove them from the package.',
  );
}

/* ------------------------------------------------------------ PNG decode ----*/

const PNG_SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

const paeth = (a, b, c) => {
  const p = a + b - c;
  const pa = Math.abs(p - a);
  const pb = Math.abs(p - b);
  const pc = Math.abs(p - c);
  return pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
};

/**
 * Decode a non-interlaced PNG into {w, h, rgba}.
 *
 * Handles colour types 6 (RGBA), 2 (RGB), 3 (palette, with tRNS) and 0
 * (greyscale), bit depths 1/2/4/8/16, and all five filter types. That is the
 * whole of what this package ships plus a margin; an interlaced file or an
 * unsupported colour type is an error rather than a guess.
 */
function decodePng(buf, label) {
  if (buf.length < 8 || !buf.subarray(0, 8).equals(PNG_SIG)) {
    fail(`${label}: not a PNG (bad signature)`);
  }
  let off = 8;
  let ihdr = null;
  let plte = null;
  let trns = null;
  const idat = [];
  while (off + 8 <= buf.length) {
    const len = buf.readUInt32BE(off);
    const type = buf.toString('latin1', off + 4, off + 8);
    if (off + 12 + len > buf.length) fail(`${label}: truncated ${type} chunk`);
    const data = buf.subarray(off + 8, off + 8 + len);
    if (type === 'IHDR') {
      ihdr = {
        w: data.readUInt32BE(0),
        h: data.readUInt32BE(4),
        depth: data[8],
        color: data[9],
        interlace: data[12],
      };
    } else if (type === 'PLTE') {
      plte = Buffer.from(data);
    } else if (type === 'tRNS') {
      trns = Buffer.from(data);
    } else if (type === 'IDAT') {
      idat.push(Buffer.from(data));
    } else if (type === 'IEND') {
      break;
    }
    off += 12 + len;
  }
  if (!ihdr) fail(`${label}: no IHDR`);
  if (ihdr.interlace !== 0) fail(`${label}: Adam7 interlacing is not supported`);
  if (idat.length === 0) fail(`${label}: no IDAT data`);

  const channels = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[ihdr.color];
  if (channels === undefined) fail(`${label}: unsupported colour type ${ihdr.color}`);
  const okDepths = { 0: [1, 2, 4, 8, 16], 2: [8, 16], 3: [1, 2, 4, 8], 4: [8, 16], 6: [8, 16] };
  if (!okDepths[ihdr.color].includes(ihdr.depth)) {
    fail(`${label}: colour type ${ihdr.color} cannot have bit depth ${ihdr.depth}`);
  }
  if (ihdr.color === 3 && !plte) fail(`${label}: palette image without a PLTE chunk`);
  if (plte && plte.length % 3 !== 0) fail(`${label}: PLTE length is not a multiple of 3`);

  const bitsPerPixel = channels * ihdr.depth;
  const bpp = Math.max(1, Math.ceil(bitsPerPixel / 8));
  const stride = Math.ceil((ihdr.w * bitsPerPixel) / 8);
  const raw = inflateSync(Buffer.concat(idat));
  const need = (stride + 1) * ihdr.h;
  if (raw.length < need) {
    fail(`${label}: inflated ${raw.length} bytes, expected ${need} (${stride}+1)*${ihdr.h}`);
  }

  /* Undo the per-row filters. Each row is written back into a flat buffer so the
   * Sub/Up/Average/Paeth predictors read the already-reconstructed neighbours. */
  const px = Buffer.alloc(stride * ihdr.h);
  let prev = Buffer.alloc(stride);
  for (let y = 0; y < ihdr.h; y++) {
    const ft = raw[y * (stride + 1)];
    const src = raw.subarray(y * (stride + 1) + 1, y * (stride + 1) + 1 + stride);
    const cur = px.subarray(y * stride, (y + 1) * stride);
    for (let x = 0; x < stride; x++) {
      const a = x >= bpp ? cur[x - bpp] : 0;
      const b = prev[x];
      const c = x >= bpp ? prev[x - bpp] : 0;
      const v = src[x];
      let out;
      switch (ft) {
        case 0: out = v; break;
        case 1: out = v + a; break;
        case 2: out = v + b; break;
        case 3: out = v + ((a + b) >> 1); break;
        case 4: out = v + paeth(a, b, c); break;
        default: fail(`${label}: unknown PNG filter type ${ft} on row ${y}`);
      }
      cur[x] = out & 0xff;
    }
    prev = cur;
  }

  /* Sample reader: 8-bit samples come straight out, 16-bit ones collapse to their
   * high byte (the output is 8-bit), and sub-byte greyscale/palette samples are
   * scaled the way PNG specifies.
   *
   * `bit` is an index into the whole de-filtered image, not into the row, so it is
   * used on its own: adding `y * stride` on top is the classic off-by-one-row bug,
   * which reads the next row (and past the end on the last one) and still produces
   * a plausible-looking icon. It was caught by diffing this decoder's output
   * against Pillow's on all 28 package icons -- the host test's "has some opaque
   * pixels" check cannot see it. */
  const maxIn = (1 << ihdr.depth) - 1;
  const readSample = (y, x, ch) => {
    const bit = (y * ihdr.w + x) * bitsPerPixel + ch * ihdr.depth;
    const byte = px[bit >> 3];
    if (ihdr.depth === 8) return byte;
    if (ihdr.depth === 16) return byte; /* high byte of the big-endian pair */
    const shift = 8 - ihdr.depth - (bit & 7);
    const raw8 = (byte >> shift) & maxIn;
    return Math.round((raw8 * 255) / maxIn);
  };

  const rgba = Buffer.alloc(ihdr.w * ihdr.h * 4);
  for (let y = 0; y < ihdr.h; y++) {
    for (let x = 0; x < ihdr.w; x++) {
      const o = (y * ihdr.w + x) * 4;
      let r;
      let g;
      let b;
      let a = 255;
      if (ihdr.color === 6) {
        r = readSample(y, x, 0);
        g = readSample(y, x, 1);
        b = readSample(y, x, 2);
        a = readSample(y, x, 3);
      } else if (ihdr.color === 2) {
        r = readSample(y, x, 0);
        g = readSample(y, x, 1);
        b = readSample(y, x, 2);
      } else if (ihdr.color === 3) {
        const idx = ihdr.depth === 8 ? px[y * stride + x] : readIndex(y, x);
        if (idx * 3 + 2 >= plte.length) fail(`${label}: palette index ${idx} out of range`);
        r = plte[idx * 3];
        g = plte[idx * 3 + 1];
        b = plte[idx * 3 + 2];
        if (trns && idx < trns.length) a = trns[idx];
      } else if (ihdr.color === 4) {
        const gray = readSample(y, x, 0);
        r = g = b = gray;
        a = readSample(y, x, 1);
      } else {
        const gray = readSample(y, x, 0);
        r = g = b = gray;
      }
      rgba[o] = r;
      rgba[o + 1] = g;
      rgba[o + 2] = b;
      rgba[o + 3] = a;
    }
  }

  /* Raw (unscaled) palette index, needed because readSample() scales to 0..255. */
  function readIndex(y, x) {
    const bit = (y * ihdr.w + x) * bitsPerPixel;
    const byte = px[bit >> 3];
    const shift = 8 - ihdr.depth - (bit & 7);
    return (byte >> shift) & maxIn;
  }

  return { w: ihdr.w, h: ihdr.h, rgba };
}

const ICONS = [];
for (const name of ICON_NAMES) {
  const file = join(ICONS_DIR, `${name}.png`);
  const { w, h, rgba } = decodePng(readFileSync(file), `icons/${name}.png`);
  if (w !== ICON_PX || h !== ICON_PX) {
    fail(
      `icons/${name}.png is ${w}x${h}, expected ${ICON_PX}x${ICON_PX} ` +
        '(BADGE_ICON_PX in main/ui/badge_spec.h)',
    );
  }
  let opaque = 0;
  for (let i = 3; i < rgba.length; i += 4) if (rgba[i] !== 0) opaque++;
  if (opaque === 0) {
    fail(`icons/${name}.png is fully transparent -- the icon did not survive the export`);
  }
  ICONS.push({ name, rgba, opaque });
}

/* --------------------------------------------------------- sounds: WAVs -----*/

const sounds = S.sounds || {};
for (const key of SND_SPEC_KEYS) {
  if (typeof sounds[key] !== 'string' || sounds[key] === '') {
    fail(`badge_spec.json "sounds.${key}" is missing or empty`);
  }
}

/** Parse a canonical PCM WAV and return its samples as an Int16Array. */
function readWav(buf, label) {
  if (buf.length < 12 || buf.toString('latin1', 0, 4) !== 'RIFF' ||
      buf.toString('latin1', 8, 12) !== 'WAVE') {
    fail(`${label}: not a RIFF/WAVE file`);
  }
  let off = 12;
  let fmt = null;
  let data = null;
  while (off + 8 <= buf.length) {
    const id = buf.toString('latin1', off, off + 4);
    const len = buf.readUInt32LE(off + 4);
    const body = buf.subarray(off + 8, Math.min(off + 8 + len, buf.length));
    if (id === 'fmt ') {
      fmt = {
        format: body.readUInt16LE(0),
        channels: body.readUInt16LE(2),
        rate: body.readUInt32LE(4),
        bits: body.readUInt16LE(14),
      };
    } else if (id === 'data') {
      data = Buffer.from(body);
    }
    off += 8 + len + (len & 1);
  }
  if (!fmt) fail(`${label}: no fmt chunk`);
  if (!data) fail(`${label}: no data chunk`);
  if (fmt.format !== 1) fail(`${label}: WAVE format ${fmt.format} is not uncompressed PCM`);
  if (fmt.channels !== 1) fail(`${label}: ${fmt.channels} channels, expected mono`);
  if (fmt.rate !== PCM_RATE) {
    fail(`${label}: ${fmt.rate} Hz, expected BADGE_PCM_RATE (${PCM_RATE})`);
  }
  if (fmt.bits !== 16) fail(`${label}: ${fmt.bits}-bit, expected 16`);
  if (data.length % 2 !== 0) fail(`${label}: data length ${data.length} is not a whole number of samples`);
  const out = new Int16Array(data.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = data.readInt16LE(i * 2);
  return out;
}

/*
 * The package ships both the WAVs and sounds/badge_sounds.c, which is the same
 * audio as C arrays. Parse that file too and require the two to agree: the WAV is
 * what gets vendored, badge_sounds.c is what the reference plays, and a mismatch
 * means one of them was replaced by hand.
 */
function badgeSoundsC() {
  const p = join(SOUNDS_DIR, 'badge_sounds.c');
  if (!existsSync(p)) return null;
  const text = readFileSync(p, 'utf8');
  const arrays = new Map();
  for (const m of text.matchAll(
    /const int16_t SND_PCM_([A-Z0-9_]+)\s*\[\s*\d*\s*\]\s*=\s*\{([\s\S]*?)\};/g,
  )) {
    const body = m[2].replace(/\/\*[\s\S]*?\*\//g, ' ');
    arrays.set(
      m[1],
      body
        .split(',')
        .map((s) => s.trim())
        .filter((s) => s.length > 0)
        .map(Number),
    );
  }
  return arrays;
}
const SND_C_ARRAYS = badgeSoundsC();

const SOUNDS = [];
for (let i = 0; i < SND_NAMES.length; i++) {
  const key = SND_SPEC_KEYS[i];
  const base = sounds[key];
  const file = join(SOUNDS_DIR, `${base}.wav`);
  if (!existsSync(file)) fail(`badge_spec.json maps ${SND_NAMES[i]} to ${base}.wav, which is not in ${SOUNDS_DIR}`);
  const pcm = readWav(readFileSync(file), `sounds/${base}.wav`);

  const macro = `SND_PCM_${base.toUpperCase().replace(/[^A-Z0-9]+/g, '_')}`;
  if (SND_C_ARRAYS) {
    const ref = SND_C_ARRAYS.get(macro.slice('SND_PCM_'.length));
    if (!ref) {
      fail(`sounds/badge_sounds.c has no ${macro}[] array for ${base}.wav`);
    }
    if (ref.length !== pcm.length) {
      fail(
        `sounds/${base}.wav holds ${pcm.length} samples but badge_sounds.c's ${macro}[] ` +
          `holds ${ref.length}: the package's audio and its C arrays disagree`,
      );
    }
    for (let j = 0; j < pcm.length; j++) {
      if (ref[j] !== pcm[j]) {
        fail(
          `sounds/${base}.wav and badge_sounds.c's ${macro}[] differ at sample ${j} ` +
            `(${pcm[j]} vs ${ref[j]})`,
        );
      }
    }
  }

  let first64 = 0;
  for (let j = 0; j < Math.min(64, pcm.length); j++) first64 |= pcm[j];
  let last64 = 0;
  for (let j = Math.max(0, pcm.length - 64); j < pcm.length; j++) last64 |= pcm[j];
  if (pcm.length < 128) fail(`sounds/${base}.wav is only ${pcm.length} samples`);
  if (first64 === 0 && last64 === 0) {
    fail(`sounds/${base}.wav is silent at both ends -- it is not the prompt the spec describes`);
  }
  SOUNDS.push({ snd: SND_NAMES[i], base, pcm });
}

/* --------------------------------------------------------- emit the data ----*/

const outData = [];
const d = (line) => outData.push(line);

d('/* GENERATED by tools/gen-badge-assets.mjs from badge_spec.json - do not edit.');
d(` * spec version ${S.version}. Regenerate: node tools/gen-badge-assets.mjs`);
d(' *');
d(` * ${ICONS.length} icons, ${ICON_PX}x${ICON_PX} RGBA8888, in badge_icon_names[] order.`);
d(` * ${SOUNDS.length} prompt sounds, ${PCM_RATE} Hz, 16-bit, mono, in badge_snd_t order:`);
SOUNDS.forEach((s, i) => {
  d(` *   ${i} ${s.snd}: ${s.base}.wav (${s.pcm.length} samples)`);
});
if (unreferenced.length) {
  d(' *');
  d(' * NOT emitted: the package ships these icons but badge_spec.json references none');
  d(' * of them, so they have no index in badge_icon_names[]. If they belong on the');
  d(' * glass, add them to the specification and regenerate it first:');
  unreferenced.forEach((n) => d(` *   ${n}.png`));
}
d(' */');
d('');
d('#include "badge_assets.h"');
d('#include "badge_spec_data.h"');
d('');
d('/* The icon side of the contract: every array below is 16*16*4 bytes. */');
d('_Static_assert(BADGE_ICON_PX == 16, "badge_icon_*_data is sized 16*16*4: update tools/gen-badge-assets.mjs");');
d('_Static_assert(BADGE_PCM_RATE == 16000, "the vendored PCM is 16 kHz: update tools/gen-badge-assets.mjs");');
d('');
d('/* ---------------------------------------------------------------- icons ----*/');

const hex = (v) => `0x${v.toString(16).padStart(2, '0')}`;
for (const icon of ICONS) {
  d('');
  d(`/* ${icon.name}: ${icon.opaque}/${ICON_PX * ICON_PX} pixels have a non-zero alpha */`);
  d(`static const uint8_t badge_icon_${icon.name}_data[16*16*4] = {`);
  for (let i = 0; i < icon.rgba.length; i += 16) {
    const row = [];
    for (let j = i; j < Math.min(i + 16, icon.rgba.length); j++) row.push(hex(icon.rgba[j]));
    d(`    ${row.join(', ')},`);
  }
  d('};');
}

d('');
d('/* Every icon, in badge_icon_names[] order (main/ui/badge_spec_data.c). */');
d(`const uint8_t *const badge_icon_table[BADGE_ICON_COUNT] = {`);
for (const icon of ICONS) d(`    badge_icon_${icon.name}_data, /* ${icon.name} */`);
d('};');

d('');
d('/* ---------------------------------------------------------------- sounds ---*/');
for (const s of SOUNDS) {
  d('');
  d(`/* ${s.snd}: sounds/${s.base}.wav, ${s.pcm.length} samples (${(s.pcm.length / PCM_RATE).toFixed(3)} s) */`);
  d(`static const int16_t snd_${s.base}[] = {`);
  const vals = Array.from(s.pcm);
  for (let i = 0; i < vals.length; i += 16) {
    d(`    ${vals.slice(i, i + 16).join(', ')},`);
  }
  d('};');
}

d('');
d('/* Every prompt sound, in badge_snd_t order (main/ui/badge_assets.h). */');
d('const int16_t *const badge_pcm_table[SND_COUNT] = {');
for (const s of SOUNDS) d(`    snd_${s.base}, /* ${s.snd} */`);
d('};');
d('');
d('const size_t badge_pcm_len_table[SND_COUNT] = {');
for (const s of SOUNDS) {
  d(`    sizeof(snd_${s.base}) / sizeof(snd_${s.base}[0]), /* ${s.snd} */`);
}
d('};');

/* --------------------------------------------------------- emit the code ----*/

const outCode = `/* GENERATED by tools/gen-badge-assets.mjs - do not edit.
 *
 * badge_assets: the accessors declared by main/ui/badge_assets.h, over the tables
 * in badge_assets_data.c (also generated, so --check covers it in the same pass).
 *
 * The four faces are defined by the vendored font files in main/ui/fonts/ and
 * declared extern in badge_assets.h; nothing here knows their internals.
 */
#include <string.h>

#include "badge_assets.h"
#include "badge_spec_data.h"

/* Defined by badge_assets_data.c. The per-icon and per-sound arrays are
 * file-static there; only these tables cross the translation-unit boundary. */
extern const uint8_t *const badge_icon_table[BADGE_ICON_COUNT];
extern const int16_t *const badge_pcm_table[SND_COUNT];
extern const size_t badge_pcm_len_table[SND_COUNT];

/* The body face is f20; n40 is the 40 px face the clock and the pairing code are
 * drawn with. An out-of-range id gets f16 rather than NULL: a wrong-but-legible
 * font is a better failure than a blank box. */
const lv_font_t *badge_font(int font_id)
{
    switch (font_id) {
    case BADGE_FONT_F20: return &badge_f20;
    case BADGE_FONT_F24: return &badge_f24;
    case BADGE_FONT_N40: return &badge_n40;
    case BADGE_FONT_F16:
    default: return &badge_f16;
    }
}

/* The specification's icons -- BADGE_ICON_COUNT of them, which is the 27 the element
 * tables name plus the bolt glyph (the package ships the PNG and the battery draws it
 * while charging) -- or NULL for BADGE_ICON_NONE, a {placeIcon} / {guideIcon}
 * placeholder the caller has not resolved yet, or an index past the end. */
const uint8_t *badge_icon_rgba(int icon)
{
    if (icon < 0 || icon >= BADGE_ICON_COUNT) return 0;
    return badge_icon_table[icon];
}

const char *badge_icon_name(int icon)
{
    if (icon < 0 || icon >= BADGE_ICON_COUNT) return "";
    return badge_icon_names[icon];
}

int badge_icon_index(const char *name)
{
    if (name == 0 || name[0] == '\\0') return BADGE_ICON_NONE;
    for (int i = 0; i < BADGE_ICON_COUNT; i++) {
        if (strcmp(badge_icon_names[i], name) == 0) return i;
    }
    return BADGE_ICON_NONE;
}

const int16_t *badge_pcm(int snd, size_t *len)
{
    if (len) *len = 0;
    if (snd < 0 || snd >= SND_COUNT) return 0;
    if (len) *len = badge_pcm_len_table[snd];
    return badge_pcm_table[snd];
}

size_t badge_assets_icon_bytes(void)
{
    return (size_t)BADGE_ICON_COUNT * BADGE_ICON_PX * BADGE_ICON_PX * 4u;
}
`;

/* --------------------------------------------------------------- write out --*/

const dataPath = join(UI_DIR, 'badge_assets_data.c');
const codePath = join(UI_DIR, 'badge_assets.c');
const dataText = outData.join('\n') + '\n';

const same = (path, text) => existsSync(path) && readFileSync(path, 'utf8') === text;

const stats =
  `${ICONS.length} icons (${ICONS.length * ICON_PX * ICON_PX * 4} B of RGBA), ` +
  `${SOUNDS.length} sounds (${SOUNDS.reduce((n, s) => n + s.pcm.length, 0)} samples)`;

/* A skipped PNG is a fact about the package, not a failure of this run. It is
 * reported on every run (and in --check, which is how CI sees it) because the
 * specification and the package having drifted is the thing worth knowing. */
const unreferencedNote = unreferenced.length
  ? `\ngen-badge-assets: WARNING: ${unreferenced.length} icon(s) ship in ${ICONS_DIR}\n` +
    '  but badge_spec.json references none of them, so they are NOT in the build:\n' +
    unreferenced.map((n) => `    ${n}.png`).join('\n') +
    '\n  badge_spec.h says "the 28 spec icons" while badge_spec_data.h has\n' +
    `  BADGE_ICON_COUNT ${ICON_NAMES.length}. Either the specification is missing an element that\n` +
    '  draws the icon, or the icon is not part of the set. See\n' +
    '  docs/badge-assets-integration.md; nothing is emitted for it either way.\n'
  : '';

if (CHECK_ONLY) {
  const stale = [];
  if (!same(dataPath, dataText)) stale.push(dataPath);
  if (!same(codePath, outCode)) stale.push(codePath);
  if (stale.length) {
    console.error(
      'gen-badge-assets: generated files are stale:\n  ' +
        stale.join('\n  ') +
        '\n  Run: node tools/gen-badge-assets.mjs',
    );
    process.exit(1);
  }
  console.log(`gen-badge-assets: up to date (${stats})`);
} else {
  writeFileSync(dataPath, dataText);
  writeFileSync(codePath, outCode);
  console.log(`gen-badge-assets: wrote ${stats}`);
  console.log(`  ${dataPath}`);
  console.log(`  ${codePath}`);
}
if (unreferencedNote) console.log(unreferencedNote);
